import{_ as r,a0 as o,w as i,s as u,ao as s,I as l,x as t,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful","title":"Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？","tag":"201609","desc":""},"relativePath":"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful.md","filePath":"[post].md"}'),d={name:"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful.md"};function f(k,a,m,x,g,b){const p=o("Link");return i(),u("div",null,[a[18]||(a[18]=s('<h1 id="ubuntu-的-snap、red-hat-的-flatpak-這種通吃所有發行版的打包方式真的有用嗎" tabindex="-1">Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？ <a class="header-anchor" href="#ubuntu-的-snap、red-hat-的-flatpak-這種通吃所有發行版的打包方式真的有用嗎" aria-label="Permalink to “Ubuntu 的 Snap、Red Hat 的 Flatpak 這種通吃所有發行版的打包方式真的有用嗎？”">​</a></h1><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/06/Flatpak-and-Snap-Packages.jpg" alt=""></p><p><strong>對新一代的打包格式開始滲透到 Linux 生態系統中的深入觀察</strong></p><p>最近我們聽到越來越多的有關於 Ubuntu 的 Snap 包和由 Red Hat 員工 Alexander Larsson 創造的 Flatpak （曾經叫做 xdg-app）的消息。</p><p>這兩種下一代打包方法在本質上擁有相同的目標和特點：即不依賴於第三方系統功能庫的獨立包裝。</p><p>這種 Linux 新技術方向似乎自然會讓人腦海中浮現這樣的問題：獨立包的優點/缺點是什麼？這是否讓我們擁有更好的 Linux 系統？其背後的動機是什麼？</p><p>為了回答這些問題，讓我們先深入瞭解一下 Snap 和 Flatpak。</p><h3 id="動機" tabindex="-1">動機 <a class="header-anchor" href="#動機" aria-label="Permalink to “動機”">​</a></h3>',8)),l("p",null,[a[2]||(a[2]=t("根據 ",-1)),n(p,{href:"http://flatpak.org/press/2016-06-21-flatpak-released.html"},{default:e(()=>[...a[0]||(a[0]=[t("Flatpak",-1)])]),_:1}),a[3]||(a[3]=t(" 和 ",-1)),n(p,{href:"https://insights.ubuntu.com/2016/06/14/universal-snap-packages-launch-on-multiple-linux-distros"},{default:e(()=>[...a[1]||(a[1]=[t("Snap",-1)])]),_:1}),a[4]||(a[4]=t(" 的聲明，背後的主要動機是使同一版本的應用程序能夠運行在多個 Linux 發行版。",-1))]),a[19]||(a[19]=s('<blockquote><p>“從一開始它的主要目標是允許相同的應用程序運行在各種 Linux 發行版和操作系統上。” —— Flatpak</p></blockquote><blockquote><p>“……‘snap’ 通用 Linux 包格式，使簡單的二進制包能夠完美的、安全的運行在任何 Linux 桌面、服務器、雲和設備上。” —— Snap</p></blockquote><p>説得更具體一點，站在 Snap 和 Flatpak （以下稱之為 S&amp;F）背後的人認為，Linux 平台存在碎片化的問題。</p><p>這個問題導致了開發者們需要做許多不必要的工作來使他的軟件能夠運行在各種不同的發行版上，這影響了整個平台的前進。</p><p>所以，作為 Linux 發行版（Ubuntu 和 Red Hat）的領導者，他們希望消除這個障礙，推動平台發展。</p><p>但是，是否是更多的個人收益刺激了 S&amp;F 的開發？</p><h4 id="個人收益" tabindex="-1">個人收益？ <a class="header-anchor" href="#個人收益" aria-label="Permalink to “個人收益？”">​</a></h4><p>雖然沒有任何官方聲明，但是試想一下，如果能夠創造這種可能會被大多數發行版（即便不是全部）所採用的打包方式，那麼這個項目的領導者將可能成為一個能夠決定 Linux 大船航向的重要人物。</p><h3 id="優勢" tabindex="-1">優勢 <a class="header-anchor" href="#優勢" aria-label="Permalink to “優勢”">​</a></h3><p>這種獨立包的好處多多，並且取決於不同的因素。</p><p>這些因素基本上可以歸為兩類：</p><h4 id="用户角度" tabindex="-1">用户角度 <a class="header-anchor" href="#用户角度" aria-label="Permalink to “用户角度”">​</a></h4><p><strong>+</strong> 從 Liunx 用户的觀點來看：Snap 和 Flatpak 帶來了將任何軟件包（軟件或應用）安裝在用户使用的任何發行版上的可能性。</p><p>例如你在使用一個不是很流行的發行版，由於開發工作的缺乏，它的軟件倉庫只有很稀少的包。現在，通過 S&amp;F 你就可以顯著的增加包的數量，這是一個多麼美好的事情。</p><p><strong>+</strong> 同樣，對於使用流行的發行版的用户，即使該發行版的軟件倉庫上有很多的包，他也可以在不改變它現有的功能庫的同時安裝一個新的包。</p><p>比方説, 一個 Debian 的用户想要安裝一個 “測試分支” 的包，但是他又不想將他的整個系統變成測試版（來讓該包運行在更新的功能庫上）。現在，他就可以簡單的想安裝哪個版本就安裝哪個版本，而不需要考慮庫的問題。</p><p>對於持後者觀點的人，可能基本上都是使用源文件編譯他們的包的人，然而，除非你使用類似 Gentoo 這樣基於源代碼的發行版，否則大多數用户將從頭編譯視為是一個噁心到吐的事情。</p><p><strong>+</strong> 高級用户，或者稱之為 “擁有安全意識的用户” 可能會覺得更容易接受這種類型的包，只要它們來自可靠來源，這種包傾向於提供另一層隔離，因為它們通常是與系統包想隔離的。</p><p>* 不論是 Snap 還是 Flatpak 都在不斷努力增強它們的安全性，通常他們都使用 “沙盒化” 來隔離，以防止它們可能攜帶病毒感染整個系統，就像微軟 Windows 系統中的 .exe 程序一樣。（關於微軟和 S&amp;F 後面還會談到）</p><h4 id="開發者角度" tabindex="-1">開發者角度 <a class="header-anchor" href="#開發者角度" aria-label="Permalink to “開發者角度”">​</a></h4><p>與普通用户相比，對於開發者來説，開發 S&amp;F 包的優點可能更加清楚。這一點已經在上一節有所提示。</p><p>儘管如此，這些優點有：</p><p><strong>+</strong> S&amp;F 通過統一開發的過程，將多發行版的開發變得簡單了起來。對於需要將他的應用運行在多個發行版的開發者來説，這大大的減少了他們的工作量。</p><p><strong>++</strong> 因此，開發者能夠更容易的使他的應用運行在更多的發行版上。</p><p><strong>+</strong> S&amp;F 允許開發者私自發布他的包，不需要依靠發行版維護者在每一個/每一次發行版中發佈他的包。</p><p><strong>++</strong> 通過上述方法，開發者可以不依賴發行版而直接獲取到用户安裝和卸載其軟件的統計數據。</p><p><strong>++</strong> 同樣是通過上述方法，開發者可以更好的直接與用户互動，而不需要通過中間媒介，比如發行版這種中間媒介。</p><h3 id="缺點" tabindex="-1">缺點 <a class="header-anchor" href="#缺點" aria-label="Permalink to “缺點”">​</a></h3><p><strong>–</strong> 膨脹。就是這麼簡單。Flatpak 和 Snap 並不是憑空變出來它的依賴關係。相反，它是通過將依賴關係預構建在其中來代替使用系統中的依賴關係。</p><p>就像諺語説的：“山不來就我，我就去就山”。</p><p><strong>–</strong> 之前提到安全意識強的用户會喜歡 S&amp;F 提供的額外的一層隔離，只要該應用來自一個受信任的來源。但是從另外一個角度看，對這方面瞭解較少的用户，可能會從一個不靠譜的地方弄來一個包含惡意軟件的包從而導致危害。</p><p>上面提到的觀點可以説是有很有意義的，雖説今天的流行方法，像 PPA、overlay 等也可能是來自不受信任的來源。</p><p>但是，S&amp;F 包更加增加這個風險，因為惡意軟件開發者只需要開發一個版本就可以感染各種發行版。相反，如果沒有 S&amp;F，惡意軟件的開發者就需要創建不同的版本以適應不同的發行版。</p><h3 id="原來微軟一直是正確的嗎" tabindex="-1">原來微軟一直是正確的嗎？ <a class="header-anchor" href="#原來微軟一直是正確的嗎" aria-label="Permalink to “原來微軟一直是正確的嗎？”">​</a></h3><p>考慮到上面提到的，很顯然，在大多數情況下，使用 S&amp;F 包的優點超過缺點。</p><p>至少對於二進制發行版的用户，或者重點不是輕量級的發行版的用户來説是這樣的。</p><p>這促使我問出這個問題，可能微軟一直是正確的嗎？如果是的，那麼當 S&amp;F 變成 Linux 的標準後，你還會一如既往的使用 Linux 或者類 Unix 系統嗎？</p><p>很顯然，時間會是這個問題的最好答案。</p><p>不過，我認為，即使不完全正確，但是微軟有些地方也是值得讚揚的，並且以我的觀點來看，所有這些方式在 Linux 上都立馬能用也確實是一個亮點。</p><hr>',40)),l("p",null,[a[6]||(a[6]=t("via: ",-1)),n(p,{href:"http://www.iwillfolo.com/ubuntus-snap-red-hats-flatpack-and-is-one-fits-all-linux-packages-useful/"},{default:e(()=>[...a[5]||(a[5]=[t("http://www.iwillfolo.com/ubuntus-snap-red-hats-flatpack-and-is-one-fits-all-linux-packages-useful/",-1)])]),_:1})]),l("p",null,[a[10]||(a[10]=t("作者：",-1)),n(p,{href:"http://www.iwillfolo.com/category/editorials/"},{default:e(()=>[...a[7]||(a[7]=[t("Editorials",-1)])]),_:1}),a[11]||(a[11]=t(" 譯者：",-1)),n(p,{href:"https://github.com/Chao-zhi"},{default:e(()=>[...a[8]||(a[8]=[t("Chao-zhi",-1)])]),_:1}),a[12]||(a[12]=t(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:e(()=>[...a[9]||(a[9]=[t("wxy",-1)])]),_:1})]),l("p",null,[a[15]||(a[15]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[13]||(a[13]=[t("LCTT",-1)])]),_:1}),a[16]||(a[16]=t(" 原創翻譯，",-1)),n(p,{href:"https://linux.cn/"},{default:e(()=>[...a[14]||(a[14]=[t("Linux中國",-1)])]),_:1}),a[17]||(a[17]=t(" 榮譽推出",-1))])])}const L=r(d,[["render",f]]);export{F as __pageData,L as default};
